document.querySelectorAll(".form-delete").forEach(t=>{t.addEventListener("submit",function(n){n.preventDefault(),Swal.fire({title:"Apakah Anda yakin?",text:"Data Pengurus OSIS yang dihapus tidak dapat dikembalikan!",icon:"warning",iconColor:"#e11d48",showCancelButton:!0,confirmButtonColor:"#e11d48",cancelButtonColor:"#64748b",confirmButtonText:"Ya, Hapus!",cancelButtonText:"Batal",background:"#ffffff",customClass:{popup:"rounded-[24px]",confirmButton:"rounded-xl font-bold px-4 py-2",cancelButton:"rounded-xl font-medium px-4 py-2"}}).then(n=>{n.isConfirmed&&t.submit()})})});